alter table public.quote_requests add column if not exists archived_at timestamptz, add column if not exists archived_by uuid references auth.users(id) on delete set null, add column if not exists archive_reason text, add column if not exists archived_previous_status text, add column if not exists archived_previous_workflow_status text;
create index if not exists quote_requests_active_created_idx on public.quote_requests(created_date desc) where status<>'archived';
create index if not exists quote_requests_archived_at_idx on public.quote_requests(archived_at desc) where status='archived';
create or replace function public.archive_quote_request(p_quote_request_id text,p_reason text default 'Archived by administrator.') returns public.quote_requests language plpgsql security definer set search_path=public,pg_temp as $$ declare result public.quote_requests; begin if not exists(select 1 from public.profiles where id=auth.uid() and role='admin') then raise exception 'Administrator access required'; end if; update public.quote_requests set archived_previous_status=case when status='archived' then archived_previous_status else status end,archived_previous_workflow_status=case when status='archived' then archived_previous_workflow_status else workflow_status end,status='archived',archived_at=coalesce(archived_at,now()),archived_by=auth.uid(),archive_reason=left(coalesce(nullif(trim(p_reason),''),'Archived by administrator.'),500),updated_date=now() where id=p_quote_request_id returning * into result; if result.id is null then raise exception 'Quote request not found'; end if; return result; end $$;
create or replace function public.restore_quote_request(p_quote_request_id text) returns public.quote_requests language plpgsql security definer set search_path=public,pg_temp as $$ declare result public.quote_requests; begin if not exists(select 1 from public.profiles where id=auth.uid() and role='admin') then raise exception 'Administrator access required'; end if; update public.quote_requests set status=coalesce(nullif(archived_previous_status,'archived'),'new'),workflow_status=coalesce(archived_previous_workflow_status,workflow_status,'quote_request_received'),archived_at=null,archived_by=null,archive_reason=null,archived_previous_status=null,archived_previous_workflow_status=null,updated_date=now() where id=p_quote_request_id and status='archived' returning * into result; if result.id is null then raise exception 'Archived quote request not found'; end if; return result; end $$;
revoke all on function public.archive_quote_request(text,text) from public,anon;revoke all on function public.restore_quote_request(text) from public,anon;grant execute on function public.archive_quote_request(text,text),public.restore_quote_request(text) to authenticated;
